INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l33','flashlight','torch','手电筒;美语 flashlight,英式 torch(高频美语点)') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
