INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l35','afterward','afterwards','以后,随后;美语常用 afterward(不带 s),英式 afterwards(课文 shortly afterward)') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
