INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l35','far more exciting','',NULL,'/fɑːr mɔːr ɪkˈsaɪtɪŋ/','He finds his new work far more exciting.','他觉得新工作有意思得多。','This one is far more expensive.','这个贵得多。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l35','rush out of','',NULL,'/rʌʃ aʊt əv/','Two thieves rushed out of a store.','两个小偷从店里冲出来。','She rushed out of the room.','她冲出了房间。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l35','such a fright that','',NULL,'/sʌtʃ ə fraɪt ðæt/','He got such a fright that he dropped the bag.','他吓得把包都扔了。','It was such a shock that she cried.','那么震惊,她哭了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l35','get away','',NULL,'/ɡet əˈweɪ/','The thieves tried to get away.','小偷企图逃跑。','You can''t get away with it.','你别想蒙混过关。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l35',5,'am2_l35_gp1','choice','{"stem":"\"These things always ___.\"(总是发生,一般现在时)","options":["have happened","will happen","happened","happen"],"answer_index":3,"stem_cn":"这些事总会发生。","explanation_cn":"\"总是发生\"是经常性事实,用一般现在时;主语 things 是复数,动词用原形。✓ These things always happen 这些事总会发生。✗ happened:那是过去;✗ have happened:完成时;✗ will happen:将来时。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l35',5,'am2_l35_gp1','choice','{"stem":"\"Roy ___ his new job very exciting these days.\"(现阶段,一般现在时)","options":["finds","has found","found","find"],"answer_index":0,"stem_cn":"罗伊觉得新工作很带劲。","explanation_cn":"现阶段的看法/状态,用一般现在时;主语 Roy 单数,动词加 -s。✓ Roy finds his job exciting 罗伊觉得工作带劲。✗ found:那是过去;✗ has found:完成时;✗ find:主语单数要加 -s。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l35',5,'am2_l35_gp2','choice','{"stem":"\"When he was driving, he ___ two thieves.\"(过去某刻,一般过去时)","options":["was seeing","has seen","saw","sees"],"answer_index":2,"stem_cn":"他开车时看到两个小偷。","explanation_cn":"过去某一刻发生的动作,用一般过去时。✓ he saw two thieves 他看到两个小偷。✗ sees:讲的是过去;✗ has seen:完成时;✗ was seeing:see 表\"看见\"一般不用进行时。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l35',5,'am2_l35_gp2','choice','{"stem":"\"Roy ___ the bus straight at the thieves.\"(过去动作,一般过去时)","options":["was driving","drove","has driven","drives"],"answer_index":1,"stem_cn":"罗伊把公交车直冲小偷开去。","explanation_cn":"过去的动作,用一般过去时。✓ Roy drove the bus at the thieves 罗伊把车冲小偷开去。✗ drives:讲过去;✗ has driven:完成时;✗ was driving:这里是一次性动作。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l35',5,'am2_l35_gp2','choice','{"stem":"\"The thief ___ the bag and ran.\"(过去动作,一般过去时)","options":["dropped","was dropping","has dropped","drops"],"answer_index":0,"stem_cn":"小偷扔下包跑了。","explanation_cn":"过去的动作,用一般过去时。✓ The thief dropped the bag and ran 小偷扔下包跑了。✗ drops:讲过去;✗ has dropped:完成时;✗ was dropping:一次性动作。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l35',5,'am2_l35_gp3','choice','{"stem":"\"He ___ not regretted becoming a bus driver.\"(与现在有联系,现在完成时)","options":["is","has","did","was"],"answer_index":1,"stem_cn":"他没后悔当公交司机。","explanation_cn":"\"没后悔\"与现在有联系,用现在完成时 has + 过去分词。✓ He has not regretted it 他没后悔。✗ did:那是一般过去;✗ was / is:不构成完成时。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l35',5,'am2_l35_gp3','choice','{"stem":"\"''What ___ happened?'' asked the policeman.\"(现在完成时)","options":["was","is","did","has"],"answer_index":3,"stem_cn":"“出什么事了?”警察问。","explanation_cn":"问\"发生了什么\"、影响到现在,用现在完成时。✓ What has happened? 出什么事了?✗ did:一般过去;✗ was / is:不构成完成时。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l35',5,'am2_l35_gp4','choice','{"stem":"\"Roy ___ drive a taxi, but now he drives a bus.\"(过去经常做、现已停止)","options":["use to","is used to","used to","was used to"],"answer_index":2,"stem_cn":"罗伊过去开出租车,现在开公交。","explanation_cn":"过去经常做、现已停止,用 used to + 原形。✓ Roy used to drive a taxi 罗伊过去开出租车。✗ use to:肯定句用 used to;✗ is used to / was used to:意为\"习惯于\",不合。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l35',5,'am2_l35_gp4','choice','{"stem":"\"He ___ work long hours when he was young.\"(过去经常做、现已停止)","options":["use to","used to","uses to","is used to"],"answer_index":1,"stem_cn":"他年轻时常长时间工作。","explanation_cn":"过去经常做、现已停止,用 used to。✓ He used to work long hours 他过去常长时间工作。✗ use to:肯定句用 used to;✗ uses to / is used to:形式或意义不对。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l35',5,'am2_l35_gp5','choice','{"stem":"\"Both men ___ arrested by the police.\"(被动,一般过去,复数)","options":["are","was","did","were"],"answer_index":3,"stem_cn":"两人都被警察逮捕了。","explanation_cn":"被动语态,主语复数(men),一般过去用 were + 过去分词。✓ Both men were arrested 两人都被逮捕。✗ was:主语是复数;✗ are:讲的是过去;✗ did:不构成被动。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l35',5,'am2_l35_gp5','choice','{"stem":"\"The thieves'' car ___ badly damaged in the crash.\"(被动,一般过去,单数)","options":["is","was","did","were"],"answer_index":1,"stem_cn":"小偷的车在撞击中严重损坏。","explanation_cn":"被动语态,主语单数(car),一般过去用 was + 过去分词。✓ The car was badly damaged 车严重损坏。✗ were:主语是单数;✗ is:讲过去;✗ did:不构成被动。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l35',5,'am2_l35_gp5','choice','{"stem":"\"The stolen money ___ found in the bag.\"(被动,一般过去)","options":["was","is","did","were"],"answer_index":0,"stem_cn":"被偷的钱在包里被找到。","explanation_cn":"被动语态,一般过去用 was + found。✓ The money was found in the bag 钱在包里被找到。✗ were:主语单数;✗ is:讲过去;✗ did:不构成被动。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l35',5,'am2_l35_gp6','choice','{"stem":"\"Yesterday Roy ___ his bus into their car.\"(yesterday 明确过去)","options":["drives","has driven","drove","drive"],"answer_index":2,"stem_cn":"昨天罗伊把车撞进他们车里。","explanation_cn":"yesterday 是明确的过去时间,用一般过去时。✓ Yesterday Roy drove his bus into their car 昨天罗伊把车撞进他们车里。✗ drives:讲过去;✗ has driven:完成时;✗ drive:主语单数要变形。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l35',5,'am2_l35_gp6','choice','{"stem":"\"So far he ___ not regretted his choice.\"(so far,现在完成时)","options":["is","has","was","did"],"answer_index":1,"stem_cn":"到目前为止他不后悔自己的选择。","explanation_cn":"so far(到目前为止)与现在有联系,用现在完成时。✓ So far he has not regretted it 到目前他不后悔。✗ did:一般过去;✗ was / is:不构成完成时。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l35',5,'am2_l35_gp7','choice','{"stem":"\"He finds his new work ___ more exciting.\"(表''…得多'',修饰比较级)","options":["far","very","too","so"],"answer_index":0,"stem_cn":"他觉得新工作有意思得多。","explanation_cn":"表示程度\"…得多\",修饰比较级用 far(或 much)。✓ far more exciting 有意思得多。✗ very:不修饰比较级 more;✗ too / so:不与 more 构成\"…得多\"。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l35',5,'am2_l35_gp7','choice','{"stem":"\"This car is ___ better than that one.\"(表''…得多'',修饰比较级)","options":["quite","too","far","very"],"answer_index":2,"stem_cn":"这辆车比那辆好得多。","explanation_cn":"表示\"…得多\",修饰比较级 better 用 far。✓ far better 好得多。✗ very:不修饰比较级;✗ too / quite:不与 better 构成\"…得多\"。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l35',5,'am2_l35_gp8','choice','{"stem":"\"He got ___ a fright that he dropped the bag.\"(如此…以至于,后接名词)","options":["too","such","so","very"],"answer_index":1,"stem_cn":"他吓得把包都扔了。","explanation_cn":"\"如此…以至于\",后面接名词(a fright)用 such。✓ such a fright that he dropped the bag 吓得扔了包。✗ so:so 后接形容词/副词,不直接接名词;✗ very / too:不与 that 构成结果。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l35',5,'am2_l35_gp8','choice','{"stem":"\"It was ___ a shock that she could not speak.\"(如此…以至于,后接名词)","options":["too","very","such","so"],"answer_index":2,"stem_cn":"那么震惊,她说不出话。","explanation_cn":"\"如此…以至于\",后接名词(a shock)用 such。✓ such a shock that she could not speak 震惊得说不出话。✗ so:so 后接形容词/副词;✗ very / too:不与 that 构成结果。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l35',6,NULL,'choice','{"stem":"美语里\"商店\"常说:","options":["sell house","shop","store","goods room"],"answer_index":2,"explanation_cn":"美语里\"商店\"常说 store;英式说 shop。✓ rush out of a store 从商店冲出来。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l35',6,NULL,'choice','{"stem":"美语里\"以后、随后\"常写作(不带 s):","options":["afterward","laterward","afterhand","afterwards"],"answer_index":0,"explanation_cn":"美语里\"以后、随后\"常写作 afterward(不带 s);英式写 afterwards。✓ shortly afterward 没过多久。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l35',6,NULL,'choice','{"stem":"regret 的意思是:","options":["忘记","高兴","期待","后悔"],"answer_index":3,"explanation_cn":"regret = 后悔。✓ he has not regretted it 他没后悔。\n顺带记:冲、奔 = rush;行动 = act;害怕 = fright."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l35',6,NULL,'choice','{"stem":"rush 的意思是:","options":["躲藏","慢走","冲,奔","停下"],"answer_index":2,"explanation_cn":"rush = 冲、奔。✓ rush out of a store 从店里冲出来。\n顺带记:后悔 = regret;径直 = straight;一段时间 = while."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l35',6,NULL,'choice','{"stem":"fright 的意思是:","options":["愤怒","好奇","喜悦","害怕,惊吓"],"answer_index":3,"explanation_cn":"fright = 害怕、惊吓。✓ got such a fright 吓了一大跳。\n顺带记:后悔 = regret;冲 = rush;撞坏的 = battered."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l35',6,NULL,'choice','{"stem":"battered 的意思是:","options":["撞坏的,破旧的","崭新的","昂贵的","巨大的"],"answer_index":0,"explanation_cn":"battered = 撞坏的、破旧的。✓ the battered car 撞坏的车。\n顺带记:径直 = straight;很快 = shortly;以后 = afterward."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l35',7,NULL,'cloze','{"stem":"第 1 空","context":"Roy ___1___ to drive a taxi, but now he drives a bus. Recently he ___2___ two thieves rush out of a store. He drove his bus at them, and shortly afterward both men ___3___ arrested. Roy ___4___ not regretted his new job.","blank_no":1,"options":["used","use","uses","is used"],"answer_index":0,"explanation_cn":"过去经常做、现已停止,用 used to。✓ Roy used to drive a taxi 罗伊过去开出租车。\n✗ use:肯定句用 used;✗ uses:时态不对;✗ is used:意为\"习惯于\"。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l35',7,NULL,'cloze','{"stem":"第 2 空","context":"Roy ___1___ to drive a taxi, but now he drives a bus. Recently he ___2___ two thieves rush out of a store. He drove his bus at them, and shortly afterward both men ___3___ arrested. Roy ___4___ not regretted his new job.","blank_no":2,"options":["saw","sees","has seen","was seeing"],"answer_index":0,"explanation_cn":"过去某刻发生,用一般过去时。✓ he saw two thieves rush out 他看到两个小偷冲出来。\n✗ sees:讲过去;✗ has seen:完成时;✗ was seeing:see 不用进行时。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l35',7,NULL,'cloze','{"stem":"第 3 空","context":"Roy ___1___ to drive a taxi, but now he drives a bus. Recently he ___2___ two thieves rush out of a store. He drove his bus at them, and shortly afterward both men ___3___ arrested. Roy ___4___ not regretted his new job.","blank_no":3,"options":["were","was","are","did"],"answer_index":0,"explanation_cn":"被动,主语复数(men),一般过去用 were + 过去分词。✓ both men were arrested 两人都被捕。\n✗ was:主语复数;✗ are:讲过去;✗ did:不构成被动。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l35',7,NULL,'cloze','{"stem":"第 4 空","context":"Roy ___1___ to drive a taxi, but now he drives a bus. Recently he ___2___ two thieves rush out of a store. He drove his bus at them, and shortly afterward both men ___3___ arrested. Roy ___4___ not regretted his new job.","blank_no":4,"options":["has","did","was","is"],"answer_index":0,"explanation_cn":"\"没后悔\"与现在有联系,用现在完成时 has。✓ Roy has not regretted his new job 罗伊没后悔。\n✗ did:一般过去;✗ was / is:不构成完成时。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l35',8,NULL,'choice','{"stem":"What job does Roy Trenton do now?","options":["He is a police officer","He is a bus driver","He is a taxi driver","He is a shop owner"],"answer_index":1,"explanation_cn":"课文说 he became a bus driver,罗伊现在是公交车司机。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l35',8,NULL,'choice','{"stem":"What did Roy do when he saw the thieves?","options":["He drove his bus straight at them","He hid inside the bus","He called the police first","He ran after them on foot"],"answer_index":0,"explanation_cn":"课文说 Roy drove the bus straight at the thieves,他把车直冲小偷开去。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l35',8,NULL,'choice','{"stem":"What happened to the thieves in the end?","options":["They got away with the money","They crashed into a store","They gave the money back","The police stopped their car and arrested both men"],"answer_index":3,"explanation_cn":"课文结尾 the police stopped the car and both men were arrested,警察截车抓了两人。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l35',9,NULL,'choice','{"stem":"你想说\"他过去开出租车\"(过去经常用 used to):","options":["He is used to drive a taxi.","He use to drive a taxi.","He used to drive a taxi.","He was used to drive a taxi."],"answer_index":2,"explanation_cn":"\"过去经常\"用 used to + 原形。✓ He used to drive a taxi. 场合:说自己过去的职业/习惯,现在已变。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l35',9,NULL,'choice','{"stem":"你想说\"两个小偷都被捕了\"(被动:were + 过去分词):","options":["Both thieves arrested.","Both thieves are arrest.","Both thieves were arrest.","Both thieves were arrested."],"answer_index":3,"explanation_cn":"被动语态用 be + 过去分词;两个人(复数)时 be 用 were。✓ Both thieves were arrested. 场合:说某人\"被…\"。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l35',9,NULL,'choice','{"stem":"你想说\"他觉得新工作有意思得多\"(far 修饰比较级):","options":["He finds his new work far more exciting.","He finds his new work very more exciting.","He finds his new work more far exciting.","He finds his new work far exciting."],"answer_index":0,"explanation_cn":"far 修饰比较级 more exciting,表\"…得多\"。✓ far more exciting. 场合:说程度上\"…得多\"。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l35',10,NULL,'choice','{"stem":"regret 的意思是:","options":["害怕","后悔","期待","高兴"],"answer_index":1,"explanation_cn":"regret = 后悔。✓ he has not regretted it 他没后悔。\n顺带记:高兴 = glad;害怕 = fright;期待 = expect."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l35',10,NULL,'choice','{"stem":"rush 的意思是:","options":["冲,奔","散步","坐下","停下"],"answer_index":0,"explanation_cn":"rush = 冲、奔。✓ rush out of a store 从店里冲出来。\n顺带记:散步 = walk;停下 = stop;坐下 = sit."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l35',10,NULL,'choice','{"stem":"\"Roy ___ not regretted his new job.\"(现在完成时)","options":["is","did","has","was"],"answer_index":2,"stem_cn":"罗伊没有后悔他的新工作。","explanation_cn":"\"没后悔\"与现在有联系,用现在完成时 has + 过去分词。✓ Roy has not regretted his new job 罗伊没后悔新工作。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l35',10,NULL,'choice','{"stem":"\"Both men ___ arrested by the police.\"(被动,一般过去)","options":["did","was","are","were"],"answer_index":3,"stem_cn":"两人都被警察逮捕了。","explanation_cn":"被动语态,主语复数,一般过去用 were + 过去分词。✓ Both men were arrested 两人都被逮捕。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l35',10,NULL,'choice','{"stem":"\"He is finding his new work far more exciting.\" 这句话的意思是:","options":["他觉得新工作有意思得多。","他不喜欢新工作。","他想换回旧工作。","他的新工作很轻松。"],"answer_index":0,"explanation_cn":"He is finding his new work far more exciting. far more exciting 表\"有意思得多\",意思是\"他觉得新工作有意思得多\"。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l35',10,NULL,'choice','{"stem":"\"The thieves tried to get away in their car.\" 这句话的意思是:","options":["小偷停下了车。","小偷把车卖了。","小偷企图开车逃跑。","小偷修好了车。"],"answer_index":2,"explanation_cn":"The thieves tried to get away in their car. get away 表\"逃跑\",意思是\"小偷企图开车逃跑\"。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l35',10,NULL,'choice','{"stem":"Why does Roy like his new job better?","options":["He works fewer hours","He can drive faster","It pays much more money","He finds being a bus driver far more exciting"],"answer_index":3,"passage":"Roy Trenton used to drive a taxi. A short while ago, however, he became a bus driver and he has not regretted it. He is finding his new work far more exciting. When he was driving along Catford Street recently, he saw two thieves rush out of a store and run toward a waiting car. One of them was carrying a bag full of money. Roy acted quickly and drove the bus straight at the thieves. The one with the money got such a fright that he dropped the bag. As the thieves were trying to get away in their car, Roy drove his bus into the back of it. While the battered car was moving away, Roy stopped his bus and telephoned the police. The thieves'' car was badly damaged and easy to recognize, and shortly afterward, the police stopped the car and both men were arrested.","explanation_cn":"课文说 He is finding his new work far more exciting,他觉得当公交司机比开出租车有意思得多。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l35',10,NULL,'choice','{"stem":"How did Roy stop the thieves?","options":["He blocked the road with his taxi","He shouted for help","He drove his bus at them and into their car, then called the police","He chased them on foot"],"answer_index":2,"passage":"Roy Trenton used to drive a taxi. A short while ago, however, he became a bus driver and he has not regretted it. He is finding his new work far more exciting. When he was driving along Catford Street recently, he saw two thieves rush out of a store and run toward a waiting car. One of them was carrying a bag full of money. Roy acted quickly and drove the bus straight at the thieves. The one with the money got such a fright that he dropped the bag. As the thieves were trying to get away in their car, Roy drove his bus into the back of it. While the battered car was moving away, Roy stopped his bus and telephoned the police. The thieves'' car was badly damaged and easy to recognize, and shortly afterward, the police stopped the car and both men were arrested.","explanation_cn":"课文说罗伊把车冲小偷开去、撞进他们车里,再停车报警,把小偷制服。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l35',10,NULL,'choice','{"stem":"How did Roy stop the thieves?","options":["He drove his bus straight at them and into their car","He followed them home","He set up a roadblock","He jumped out and caught them"],"answer_index":0,"audio":"Roy Trenton used to drive a taxi. A short while ago, however, he became a bus driver and he has not regretted it. He is finding his new work far more exciting. When he was driving along Catford Street recently, he saw two thieves rush out of a store and run toward a waiting car. One of them was carrying a bag full of money. Roy acted quickly and drove the bus straight at the thieves. The one with the money got such a fright that he dropped the bag. As the thieves were trying to get away in their car, Roy drove his bus into the back of it. While the battered car was moving away, Roy stopped his bus and telephoned the police. The thieves'' car was badly damaged and easy to recognize, and shortly afterward, the police stopped the car and both men were arrested.","explanation_cn":"课文说 Roy drove the bus straight at the thieves… drove his bus into the back of it,他用公交车拦截小偷。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l35',10,NULL,'choice','{"stem":"Why was the thieves'' car easy to recognize?","options":["It had no license plate","It was brand new","It was badly damaged (battered)","It was bright red"],"answer_index":2,"audio":"Roy Trenton used to drive a taxi. A short while ago, however, he became a bus driver and he has not regretted it. He is finding his new work far more exciting. When he was driving along Catford Street recently, he saw two thieves rush out of a store and run toward a waiting car. One of them was carrying a bag full of money. Roy acted quickly and drove the bus straight at the thieves. The one with the money got such a fright that he dropped the bag. As the thieves were trying to get away in their car, Roy drove his bus into the back of it. While the battered car was moving away, Roy stopped his bus and telephoned the police. The thieves'' car was badly damaged and easy to recognize, and shortly afterward, the police stopped the car and both men were arrested.","explanation_cn":"课文说 The thieves'' car was badly damaged and easy to recognize,车被撞坏所以容易辨认。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l36',2,5,36,'Across the Channel','横渡海峡','be going to + 动词原形(表打算/计划的将来,可替代 will/shall,KS12)主考——is/are/am going to、疑问否定、条件句结果部分用 will 不用 going to + will 表将来 / 将来进行时 will be doing(he will be watching)+ intend to do / 倒装 Among them will be…(辅考·课文①类)','黛比·哈特准备明天横渡英吉利海峡。她打算早上5点从法国海岸出发。黛比只有11岁,希望创一项新的世界纪录。她是个游泳能手,很多人认为她一定能成功。黛比的父亲将乘一条小船同她一道出发;哈特先生训练女儿已经多年,明天他将焦急地注视着女儿游过这段漫长的距离到达英国。黛比计划每两小时休息一下,只喝饮料、不吃固体食物。黛比的大部分同学将在英国海岸等候她;他们当中还会有黛比的母亲——她本人还是个姑娘时,也曾横渡过英吉利海峡!','{"q":"Listen and answer — What is Debbie going to try to do?","options":["Swim across the English Channel","Sail a boat across the sea","Break a running record","Learn to swim"],"answer_index":0}'::jsonb,'{"title":"be going to:打算做的将来","intro":"be going to + 动词原形,表示打算、计划要做的事,常可替代 will / shall。be 随主语变:I am / he·she·it is / you·we·they are going to。全用本课和 Key structure 的句子举例。","table":{"headers":["表达","例子"],"rows":[["I am going to …","I am going to travel by air."],["he/she is going to …","She is going to swim across the Channel."],["they are going to …","They are going to move to a new house."],["will 表将来(预测 / 自然会)","She will have something to drink."],["将来进行时 will be + doing","He will be watching her anxiously."]]},"specialRules":[{"rule":"条件句结果部分用 will,不用 going to:You will enjoy yourself if you travel by sea.","mark":"条件句用 will"},{"rule":"intend to do / mean to do = 打算做(≈ be going to);倒装:Among them will be Debbie''s mother = Debbie''s mother will be among them.","mark":"intend / 倒装"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l36',1,NULL,'Debbie Hart is going to swim across the English Channel tomorrow.','黛比·哈特打算明天横渡英吉利海峡。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l36',2,NULL,'She is going to set out from the French coast at five o''clock in the morning.','她打算早上5点从法国海岸出发。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l36',3,NULL,'Debbie is only eleven years old, and she hopes to set up a new world record.','黛比只有11岁,她希望创一项新的世界纪录。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l36',4,NULL,'She is a strong swimmer, and many people feel that she is sure to succeed.','她是个游泳能手,很多人认为她一定能成功。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l36',5,NULL,'Debbie''s father will set out with her in a small boat.','黛比的父亲将乘一条小船同她一道出发。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l36',6,NULL,'Mr. Hart has trained his daughter for years, and tomorrow he will be watching her anxiously as she swims the long distance to England.','哈特先生训练女儿已经多年,明天他将焦急地注视着女儿游过这段漫长的距离到达英国。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l36',7,NULL,'Debbie intends to take short rests every two hours.','黛比打算每两小时休息一下。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l36',8,NULL,'She will have something to drink, but she will not eat any solid food.','她将喝些饮料,但不吃任何固体食物。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l36',9,NULL,'Most of Debbie''s school friends will be waiting for her on the English coast.','黛比的大部分同学将在英国海岸等候她。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l36',10,NULL,'Among them will be Debbie''s mother, who swam the Channel herself when she was a girl.','他们当中还会有黛比的母亲——她本人还是个姑娘时,也曾横渡过英吉利海峡。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
