INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l36','movie','film','电影;美语 movie,英式 film(高频美语点)') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l36','be going to do','',NULL,'/bi ˈɡoʊɪŋ tuː duː/','Debbie is going to swim across the Channel.','黛比打算横渡海峡。','I am going to travel by air.','我打算坐飞机去。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l36','set up a record','',NULL,'/set ʌp ə ˈrekərd/','She hopes to set up a new world record.','她希望创一项新的世界纪录。','He set up a new company.','他创办了一家新公司。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l36','be sure to do','',NULL,'/bi ʃʊr tuː duː/','Many people feel she is sure to succeed.','许多人认为她一定能成功。','He is sure to come.','他一定会来。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l36','intend to do','',NULL,'/ɪnˈtend tuː duː/','Debbie intends to take short rests.','黛比打算休息一下。','I intend to stay here.','我打算留在这儿。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l36',5,'am2_l36_gp1','choice','{"stem":"\"Debbie ___ going to swim across the Channel.\"(表打算,be 随主语变)","options":["be","am","is","are"],"answer_index":2,"stem_cn":"黛比打算横渡海峡。","explanation_cn":"be going to 表打算,主语 Debbie 单数,be 用 is。✓ Debbie is going to swim 黛比打算游泳。✗ are:主语单数;✗ am:只配 I;✗ be:要用具体形式。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l36',5,'am2_l36_gp1','choice','{"stem":"\"They ___ going to move to a new house.\"(表打算,复数)","options":["be","are","am","is"],"answer_index":1,"stem_cn":"他们打算搬新家。","explanation_cn":"be going to 表打算,主语 They 复数,be 用 are。✓ They are going to move 他们打算搬家。✗ is:主语复数;✗ am:只配 I;✗ be:要用具体形式。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l36',5,'am2_l36_gp1','choice','{"stem":"\"I ___ going to write to him.\"(表打算,第一人称)","options":["am","is","be","are"],"answer_index":0,"stem_cn":"我打算给他写信。","explanation_cn":"be going to 表打算,主语 I,be 用 am。✓ I am going to write 我打算写信。✗ is / are:不配 I;✗ be:要用具体形式。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l36',5,'am2_l36_gp2','choice','{"stem":"\"She is going to ___ across the Channel.\"(be going to 后接动词原形)","options":["swimming","swam","swim","swims"],"answer_index":2,"stem_cn":"她打算横渡海峡。","explanation_cn":"be going to 后面接动词原形。✓ is going to swim 打算游泳。✗ swims:后面不加 -s;✗ swimming / swam:不用 -ing 或过去式。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l36',5,'am2_l36_gp2','choice','{"stem":"\"They are going to ___ to a new house.\"(be going to 后接动词原形)","options":["move","moved","moves","moving"],"answer_index":0,"stem_cn":"他们打算搬去新房子。","explanation_cn":"be going to 后面接动词原形。✓ are going to move 打算搬家。✗ moves / moving / moved:be going to 后只接原形。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l36',5,'am2_l36_gp3','choice','{"stem":"\"___ she going to set out at five?\"(be going to 一般疑问)","options":["Does","Will","Is","Are"],"answer_index":2,"stem_cn":"她打算5点出发吗?","explanation_cn":"be going to 的一般疑问,把 be 提前;主语单数用 Is。✓ Is she going to set out? 她打算出发吗?✗ Does:be going to 不用 do 提问;✗ Will:那是 will 的疑问;✗ Are:主语单数。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l36',5,'am2_l36_gp3','choice','{"stem":"\"Debbie is ___ going to eat any solid food.\"(be going to 否定)","options":["not","no","don''t","won''t"],"answer_index":0,"stem_cn":"黛比不打算吃固体食物。","explanation_cn":"be going to 的否定在 be 后面加 not。✓ is not going to eat 不打算吃。✗ don''t:be going to 不用 do 否定;✗ won''t:那是 will not;✗ no:不能直接否定动词。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l36',5,'am2_l36_gp4','choice','{"stem":"\"Her father ___ set out with her in a boat.\"(表将来的预测)","options":["has","is","will","was"],"answer_index":2,"stem_cn":"她父亲将乘小船同她出发。","explanation_cn":"表示对将来的预测,用 will + 动词原形。✓ Her father will set out with her 她父亲将同她出发。✗ is / was / has:不构成将来时。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l36',5,'am2_l36_gp4','choice','{"stem":"\"Most of her friends ___ wait on the coast.\"(表将来)","options":["have","were","are","will"],"answer_index":3,"stem_cn":"她大部分朋友将在海岸等候。","explanation_cn":"表示将来,用 will。✓ Most of her friends will wait 她的朋友们将等候。✗ are:缺将来含义;✗ were:过去;✗ have:完成时。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l36',5,'am2_l36_gp5','choice','{"stem":"\"Tomorrow he ___ be watching her anxiously.\"(将来某时正在进行)","options":["will","is","has","was"],"answer_index":0,"stem_cn":"明天他将焦急地看着她。","explanation_cn":"将来某时正在进行,用 will be + doing。✓ he will be watching her 他将看着她。✗ is:讲的是明天;✗ was:过去;✗ has:完成时。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l36',5,'am2_l36_gp5','choice','{"stem":"\"This time tomorrow she ___ be swimming the Channel.\"(将来某刻正在进行)","options":["was","is","will","has"],"answer_index":2,"stem_cn":"明天此时她将在横渡海峡。","explanation_cn":"将来某刻正在进行,用 will be + doing。✓ she will be swimming 她将在游泳。✗ is:讲的是明天;✗ was:过去;✗ has:完成时。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l36',5,'am2_l36_gp5','choice','{"stem":"\"He will ___ watching her all day tomorrow.\"(将来进行,will 后接的词)","options":["be","been","being","is"],"answer_index":0,"stem_cn":"明天他将一整天看着她。","explanation_cn":"将来进行时结构 will + be + doing,will 后面用 be。✓ will be watching 将看着。✗ been:那是完成时;✗ is / being:不构成 will be doing。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l36',5,'am2_l36_gp6','choice','{"stem":"\"Look at the clouds — it ___ going to rain.\"(眼前迹象,be going to)","options":["was","does","is","will"],"answer_index":2,"stem_cn":"看那乌云,要下雨了。","explanation_cn":"看到眼前迹象(乌云)推断将来,用 be going to。✓ it is going to rain 要下雨了。✗ will:这里 going to 已给出;✗ was:过去;✗ does:不构成将来。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l36',5,'am2_l36_gp6','choice','{"stem":"\"Don''t worry, you ___ enjoy the trip.\"(预测 / 安慰,用将来)","options":["are going","were","have","will"],"answer_index":3,"stem_cn":"别担心,你会喜欢这次旅行的。","explanation_cn":"安慰/预测将来,用 will。✓ you will enjoy the trip 你会喜欢旅行。✗ are going:与后面不搭;✗ were:过去;✗ have:完成时。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l36',5,'am2_l36_gp7','choice','{"stem":"\"Debbie intends ___ take short rests every two hours.\"(intend 后接动词不定式)","options":["at","to","of","for"],"answer_index":1,"stem_cn":"黛比打算每两小时休息一下。","explanation_cn":"intend 后面接动词不定式,用 to。✓ intends to take short rests 打算休息一下。✗ for / at / of:intend 后接不定式。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l36',5,'am2_l36_gp7','choice','{"stem":"\"She means ___ ask for an explanation.\"(mean 后接动词不定式)","options":["to","for","at","of"],"answer_index":0,"stem_cn":"她打算要求一个解释。","explanation_cn":"mean(打算)后面接动词不定式,用 to。✓ means to ask 打算询问。✗ for / at / of:mean 后接不定式。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l36',5,'am2_l36_gp8','choice','{"stem":"\"Among them ___ be Debbie''s mother, who swam the Channel.\"(倒装,表将来)","options":["is","will","was","are"],"answer_index":1,"stem_cn":"他们当中将有黛比的母亲。","explanation_cn":"倒装句(Among them …)表将来,用 will。✓ Among them will be Debbie''s mother 他们当中将有黛比的母亲。✗ is:缺将来含义;✗ are:主体单数(mother);✗ was:过去。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l36',5,'am2_l36_gp8','choice','{"stem":"\"On the coast ___ many of her school friends, waiting for her.\"(倒装,主体是复数 friends)","options":["were","being","is","was"],"answer_index":0,"stem_cn":"海岸上是等着她的许多同学。","explanation_cn":"倒装句(On the coast …),后面真正的主体是复数(many friends),用 were。✓ On the coast were many of her school friends 海岸上是许多同学。✗ was:主体是复数;✗ is:讲的是过去;✗ being:不作谓语。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l36',6,NULL,'choice','{"stem":"美语里称呼缩写(先生、博士)后常加点,写作:","options":["Mr: / Dr:","M. / D.","Mr. / Dr.","Mr / Dr"],"answer_index":2,"explanation_cn":"美语里称呼缩写后常加点:Mr. / Dr. / Mrs.;英式常不加点 Mr / Dr。✓ Mr. Hart 哈特先生。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l36',6,NULL,'choice','{"stem":"美语里\"假期\"常说:","options":["vacation","holiday","free time","rest day"],"answer_index":0,"explanation_cn":"美语里\"假期\"常说 vacation;英式说 holiday。✓ a summer vacation 暑假。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l36',6,NULL,'choice','{"stem":"record(a new world record)的意思是:","options":["回忆","比赛","纪录","唱片机"],"answer_index":2,"explanation_cn":"record(a new world record)= 纪录。✓ set up a new world record 创一项新世界纪录。\n顺带记:成功 = succeed;训练 = train;打算 = intend."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l36',6,NULL,'choice','{"stem":"succeed 的意思是:","options":["成功","失败","尝试","放弃"],"answer_index":0,"explanation_cn":"succeed = 成功。✓ she is sure to succeed 她一定能成功。\n顺带记:纪录 = record;强壮的 = strong;固体的 = solid."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l36',6,NULL,'choice','{"stem":"intend 的意思是:","options":["忘记","怀疑","打算,想要","拒绝"],"answer_index":2,"explanation_cn":"intend = 打算、想要。✓ intends to take short rests 打算休息一下。\n顺带记:成功 = succeed;训练 = train;焦急地 = anxiously."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l36',6,NULL,'choice','{"stem":"anxiously 的意思是:","options":["大声地","高兴地","缓慢地","焦急地"],"answer_index":3,"explanation_cn":"anxiously = 焦急地。✓ watching her anxiously 焦急地看着她。\n顺带记:打算 = intend;强壮的 = strong;休息 = rest."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l36',7,NULL,'cloze','{"stem":"第 1 空","context":"Debbie ___1___ going to swim across the Channel tomorrow. Her father ___2___ set out with her in a boat. He ___3___ be watching her anxiously. Among the friends on the coast ___4___ be Debbie''s mother.","blank_no":1,"options":["is","are","am","be"],"answer_index":0,"explanation_cn":"be going to 表打算,主语 Debbie 单数用 is。✓ Debbie is going to swim 黛比打算游泳。\n✗ are:主语单数;✗ am:只配 I;✗ be:要用具体形式。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l36',7,NULL,'cloze','{"stem":"第 2 空","context":"Debbie ___1___ going to swim across the Channel tomorrow. Her father ___2___ set out with her in a boat. He ___3___ be watching her anxiously. Among the friends on the coast ___4___ be Debbie''s mother.","blank_no":2,"options":["will","is","was","has"],"answer_index":0,"explanation_cn":"表将来的预测,用 will。✓ Her father will set out 她父亲将出发。\n✗ is / was / has:不构成将来时。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l36',7,NULL,'cloze','{"stem":"第 3 空","context":"Debbie ___1___ going to swim across the Channel tomorrow. Her father ___2___ set out with her in a boat. He ___3___ be watching her anxiously. Among the friends on the coast ___4___ be Debbie''s mother.","blank_no":3,"options":["will","is","was","has"],"answer_index":0,"explanation_cn":"将来某时正在进行,用 will be + doing。✓ He will be watching her 他将看着她。\n✗ is:讲明天;✗ was:过去;✗ has:完成时。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l36',7,NULL,'cloze','{"stem":"第 4 空","context":"Debbie ___1___ going to swim across the Channel tomorrow. Her father ___2___ set out with her in a boat. He ___3___ be watching her anxiously. Among the friends on the coast ___4___ be Debbie''s mother.","blank_no":4,"options":["will","is","are","was"],"answer_index":0,"explanation_cn":"倒装句表将来,用 will。✓ Among the friends will be Debbie''s mother 朋友当中将有黛比的母亲。\n✗ is:缺将来含义;✗ are:主体单数;✗ was:过去。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l36',8,NULL,'choice','{"stem":"What is Debbie going to try to do tomorrow?","options":["Train other swimmers","Sail a boat to France","Set a running record","Swim across the English Channel"],"answer_index":3,"explanation_cn":"课文说 Debbie is going to swim across the English Channel,黛比打算横渡英吉利海峡。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l36',8,NULL,'choice','{"stem":"How often does Debbie intend to rest?","options":["She will not rest at all","Every two hours","Only once","Every ten minutes"],"answer_index":1,"explanation_cn":"课文说 Debbie intends to take short rests every two hours,她打算每两小时休息一下。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l36',8,NULL,'choice','{"stem":"Who swam the Channel herself as a girl?","options":["Debbie''s older sister","A school friend","Debbie''s mother","Debbie''s teacher"],"answer_index":2,"explanation_cn":"课文结尾说 Debbie''s mother swam the Channel herself when she was a girl。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l36',9,NULL,'choice','{"stem":"你想说\"我打算坐飞机去\"(打算用 be going to):","options":["I will going to travel by air.","I am going to travel by air.","I am go to travel by air.","I going to travel by air."],"answer_index":1,"explanation_cn":"\"打算\"用 be going to + 原形;跟 I 搭配时 be 用 am。✓ I am going to travel by air. 场合:说自己打算做的事。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l36',9,NULL,'choice','{"stem":"你想说\"他明天会一直焦急地看着她\"(将来进行时 will be + doing):","options":["He will be watch her anxiously.","He is watching her anxiously.","He will be watching her anxiously.","He will watching her anxiously."],"answer_index":2,"explanation_cn":"将来进行时用 will be + doing。✓ He will be watching her anxiously. 场合:说将来某时正在进行的动作。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l36',9,NULL,'choice','{"stem":"你想说\"她一定能成功\"(be sure to do):","options":["She is sure succeed.","She sure to succeed.","She is sure to succeeding.","She is sure to succeed."],"answer_index":3,"explanation_cn":"\"一定会…\"用 be sure to do。✓ She is sure to succeed. 场合:表示很有把握某事会发生。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l36',10,NULL,'choice','{"stem":"succeed 的意思是:","options":["休息","成功","失败","出发"],"answer_index":1,"explanation_cn":"succeed = 成功。✓ she is sure to succeed 她一定能成功。\n顺带记:失败 = fail;休息 = rest;出发 = set out."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l36',10,NULL,'choice','{"stem":"intend 的意思是:","options":["拒绝","完成","害怕","打算,想要"],"answer_index":3,"explanation_cn":"intend = 打算、想要。✓ intends to take short rests 打算休息一下。\n顺带记:拒绝 = refuse;害怕 = fright;完成 = finish."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l36',10,NULL,'choice','{"stem":"\"Debbie ___ going to swim across the Channel.\"(打算,be going to)","options":["is","are","be","am"],"answer_index":0,"stem_cn":"黛比打算横渡海峡。","explanation_cn":"be going to 表打算,主语单数用 is。✓ Debbie is going to swim 黛比打算横渡海峡。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l36',10,NULL,'choice','{"stem":"\"Her father ___ set out with her tomorrow.\"(表将来的预测)","options":["has","was","is","will"],"answer_index":3,"stem_cn":"她父亲明天将同她一起出发。","explanation_cn":"表将来的预测,用 will。✓ Her father will set out with her 她父亲将同她一起出发。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l36',10,NULL,'choice','{"stem":"\"She hopes to set up a new world record.\" 这句话的意思是:","options":["她打破了世界纪录。","她观看了比赛。","她希望创一项新的世界纪录。","她放弃了比赛。"],"answer_index":2,"explanation_cn":"She hopes to set up a new world record. set up a record 表\"创纪录\",意思是\"她希望创一项新的世界纪录\"。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l36',10,NULL,'choice','{"stem":"\"She will not eat any solid food.\" 这句话的意思是:","options":["她整天不喝水。","她不会吃任何固体食物。","她只吃固体食物。","她会吃很多东西。"],"answer_index":1,"explanation_cn":"She will not eat any solid food. solid food 表\"固体食物\",意思是\"她不会吃任何固体食物\"。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l36',10,NULL,'choice','{"stem":"Why is Debbie''s swim special?","options":["She will swim without resting","She has never swum before","She is only eleven and hopes to set a new world record","She will swim at night"],"answer_index":2,"passage":"Debbie Hart is going to swim across the English Channel tomorrow. She is going to set out from the French coast at five o''clock in the morning. Debbie is only eleven years old, and she hopes to set up a new world record. She is a strong swimmer, and many people feel that she is sure to succeed. Debbie''s father will set out with her in a small boat. Mr. Hart has trained his daughter for years, and tomorrow he will be watching her anxiously as she swims the long distance to England. Debbie intends to take short rests every two hours. She will have something to drink, but she will not eat any solid food. Most of Debbie''s school friends will be waiting for her on the English coast. Among them will be Debbie''s mother, who swam the Channel herself when she was a girl.","explanation_cn":"课文说黛比只有11岁,却希望创一项新的世界纪录,所以这次横渡不同寻常。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l36',10,NULL,'choice','{"stem":"What will Debbie do during the swim?","options":["Sleep on the boat","Stop every ten minutes","Eat a big meal halfway","Take short rests every two hours and drink but not eat solid food"],"answer_index":3,"passage":"Debbie Hart is going to swim across the English Channel tomorrow. She is going to set out from the French coast at five o''clock in the morning. Debbie is only eleven years old, and she hopes to set up a new world record. She is a strong swimmer, and many people feel that she is sure to succeed. Debbie''s father will set out with her in a small boat. Mr. Hart has trained his daughter for years, and tomorrow he will be watching her anxiously as she swims the long distance to England. Debbie intends to take short rests every two hours. She will have something to drink, but she will not eat any solid food. Most of Debbie''s school friends will be waiting for her on the English coast. Among them will be Debbie''s mother, who swam the Channel herself when she was a girl.","explanation_cn":"课文说她每两小时休息一下,只喝饮料不吃固体食物。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l36',10,NULL,'choice','{"stem":"What is Debbie going to try to do?","options":["Win a running race","Train for the Olympics","Swim across the English Channel","Sail a boat alone"],"answer_index":2,"audio":"Debbie Hart is going to swim across the English Channel tomorrow. She is going to set out from the French coast at five o''clock in the morning. Debbie is only eleven years old, and she hopes to set up a new world record. She is a strong swimmer, and many people feel that she is sure to succeed. Debbie''s father will set out with her in a small boat. Mr. Hart has trained his daughter for years, and tomorrow he will be watching her anxiously as she swims the long distance to England. Debbie intends to take short rests every two hours. She will have something to drink, but she will not eat any solid food. Most of Debbie''s school friends will be waiting for her on the English coast. Among them will be Debbie''s mother, who swam the Channel herself when she was a girl.","explanation_cn":"课文说 Debbie is going to swim across the English Channel,这是她明天要做的事。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l36',10,NULL,'choice','{"stem":"Who will be waiting on the English coast?","options":["No one at all","A team of doctors","Only her father","Most of Debbie''s school friends and her mother"],"answer_index":3,"audio":"Debbie Hart is going to swim across the English Channel tomorrow. She is going to set out from the French coast at five o''clock in the morning. Debbie is only eleven years old, and she hopes to set up a new world record. She is a strong swimmer, and many people feel that she is sure to succeed. Debbie''s father will set out with her in a small boat. Mr. Hart has trained his daughter for years, and tomorrow he will be watching her anxiously as she swims the long distance to England. Debbie intends to take short rests every two hours. She will have something to drink, but she will not eat any solid food. Most of Debbie''s school friends will be waiting for her on the English coast. Among them will be Debbie''s mother, who swam the Channel herself when she was a girl.","explanation_cn":"课文说大部分同学将在英国海岸等她,其中还有她的母亲。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
